using System.Buffers.Binary;
using iTunesPod.Core;
using static iTunesPod.Infrastructure.ITunesDbWriter;
namespace iTunesPod.Infrastructure;
public static class PodcastDatabase
{
    public static byte[] GroupEpisodes(byte[] original,ReadOnlySpan<byte> identity){var tracks=new ITunesDbReader().Read(original,Path.GetTempPath()).Where(x=>x.IsPodcast).ToArray();var lists=new ITunesDbReader().ReadPlaylists(original);var podcast=lists.FirstOrDefault(x=>!x.IsSystem&&x.Name.Equals("Podcasts",StringComparison.OrdinalIgnoreCase));if(podcast==null){podcast=new("device-playlist:"+Convert.ToHexString(System.Security.Cryptography.RandomNumberGenerator.GetBytes(8)),"Podcasts",[]);original=DeviceDatabaseEdits.Apply(original,identity,playlists:lists.Append(podcast).ToArray());}var sections=Children(original,U(original,4));for(var s=0;s<sections.Count;s++){var section=sections[s];if(U(section,12) is not (2 or 3))continue;var sh=U(section,4);var lh=U(section,sh+4);var records=Children(section,sh+lh);for(var p=0;p<records.Count;p++){var record=records[p];var id="device-playlist:"+BinaryPrimitives.ReadUInt64LittleEndian(record.AsSpan(28)).ToString("X16");if(id!=podcast.Id)continue;var children=Children(record,U(record,4));var metadata=children.Where(x=>Magic(x)=="mhod").ToList();var old=children.Where(x=>Magic(x)=="mhip"&&U(x,24)!=0).GroupBy(x=>U(x,24)).ToDictionary(x=>x.Key,x=>x.First());var entries=new List<byte[]>();var groupId=1;foreach(var group in tracks.GroupBy(x=>x.Album)){if(U(section,12)==3){var h=Header("mhip",76);Put(h,12,1);BinaryPrimitives.WriteUInt16LittleEndian(h.AsSpan(16),256);Put(h,20,groupId);entries.Add(Join(h,[StringRecord(1,group.Key)]));}foreach(var track in group){var trackId=uint.Parse(track.Id[7..]);var item=old.TryGetValue((int)trackId,out var inherited)?(byte[])inherited.Clone():Item(trackId,entries.Count);if(U(item,4)<36)throw new IOException("Podcast 列表条目头不支持分组。");Put(item,32,U(section,12)==3?groupId:0);entries.Add(item);}groupId++;}var header=record.AsSpan(0,U(record,4)).ToArray();Put(header,12,metadata.Count);Put(header,16,entries.Count);if(header.Length>=44)BinaryPrimitives.WriteUInt16LittleEndian(header.AsSpan(42),1);records[p]=Join(header,metadata.Concat(entries));}sections[s]=Join(section.AsSpan(0,sh).ToArray(),[Join(section.AsSpan(sh,lh).ToArray(),records,true)]);}return DeviceChecksum.SignHash58(Join(original.AsSpan(0,U(original,4)).ToArray(),sections),identity);}
}
